class TestSchemaIntegrity:
    """Validate the database schema is correctly initialized."""

    def test_connection_is_sqlite(self, builder: DashboardBuilder):
        """The connection must be a SQLite connection."""
        assert isinstance(builder.conn, sqlite3.Connection)

    def test_test_runs_table_exists(self, builder: DashboardBuilder):
        """The `test_runs` table must be created on init."""
        cursor = builder.conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name='test_runs'"
        )
        assert cursor.fetchone() is not None

    def test_schema_columns(self, builder: DashboardBuilder):
        """Verify the exact column set and types."""
        cursor = builder.conn.execute("PRAGMA table_info(test_runs)")
        columns = {row[1]: row[2] for row in cursor.fetchall()}
        expected = {
            "timestamp": "TEXT",
            "suite": "TEXT",
            "total": "INTEGER",
            "passed": "INTEGER",
            "failed": "INTEGER",
            "duration": "REAL",
        }
        assert columns == expected

    def test_primary_key_autoincrement(self, builder: DashboardBuilder):
        """Ensure an auto-incrementing primary key exists."""
        cursor = builder.conn.execute("PRAGMA table_info(test_runs)")
        pk_columns = [row[1] for row in cursor.fetchall() if row[5] == 1]
        assert len(pk_columns) == 1
        assert pk_columns[0] == "id"

    def test_duplicate_insert_allowed(self, seeded_builder: DashboardBuilder):
        """The schema should allow multiple runs for the same suite."""
        conn = seeded_builder.conn
        conn.execute(
            "INSERT INTO test_runs (timestamp, suite, total, passed, failed, duration) VALUES (?, ?, ?, ?, ?, ?)",
            (datetime.now().isoformat(), "core", 10, 10, 0, 1.0),
        )
        conn.commit()
        count = conn.execute("SELECT COUNT(*) FROM test_runs WHERE suite='core'").fetchone()[0]
        assert count == 3  # 2 original + 1 new


