class TestAggregation:
    """Validate the `aggregate()` method."""

    def test_aggregate_returns_dataframe(self, seeded_builder: DashboardBuilder):
        """Must return a pandas DataFrame."""
        result = seeded_builder.aggregate()
        assert isinstance(result, pd.DataFrame)

    def test_aggregate_grouped_by_suite(self, seeded_builder: DashboardBuilder):
        """Result must be indexed by suite with correct aggregates."""
        result = seeded_builder.aggregate()
        assert set(result.index) == {"core", "integration"}

        # Core suite: total=200, passed=193, failed=7, duration mean=(12.5+11.2)/2
        core_row = result.loc["core"]
        assert core_row["total"] == 200
        assert core_row["passed"] == 193
        assert core_row["failed"] == 7
        assert abs(core_row["duration"] - 11.85) < 0.01

    def test_aggregate_empty_db(self, empty_builder: DashboardBuilder):
        """Empty DB should return an empty DataFrame without error."""
        result = empty_builder.aggregate()
        assert isinstance(result, pd.DataFrame)
        assert result.empty

    def test_aggregate_single_suite(self, builder: DashboardBuilder):
        """Single suite with one run."""
        conn = builder.conn
        conn.execute(
            "INSERT INTO test_runs (timestamp, suite, total, passed, failed, duration) VALUES (?, ?, ?, ?, ?, ?)",
            (datetime.now().isoformat(), "solo", 10, 9, 1, 3.5),
        )
        conn.commit()
        result = builder.aggregate()
        assert len(result) == 1
        assert result.loc["solo", "passed"] == 9

    def test_aggregate_handles_null_duration(self, builder: DashboardBuilder):
        """Null duration should be treated as 0 in mean calculation."""
        conn = builder.conn
        conn.execute(
            "INSERT INTO test_runs (timestamp, suite, total, passed, failed, duration) VALUES (?, ?, ?, ?, ?, ?)",
            (datetime.now().isoformat(), "null_dur", 5, 5, 0, None),
        )
        conn.commit()
        result = builder.aggregate()
        assert result.loc["null_dur", "duration"] == 0


