class TestIntegration:
    """Full lifecycle: seed -> aggregate -> generate -> verify."""

    def test_full_pipeline(self, seeded_builder: DashboardBuilder):
        """Complete workflow produces consistent artifacts."""
        df = seeded_builder.aggregate()
        assert not df.empty

        html_file = seeded_builder.generate_html()
        content = html_file.read_text()

        # Verify HTML reflects the aggregated data
        for suite in df.index:
            assert suite in content
        assert str(df["passed"].sum()) in content

    def test_multiple_builders_isolated(self, tmp_path: Path):
        """Two builders with different dirs must not interfere."""
        b1_artifacts = tmp_path / "a1"
        b1_output = tmp_path / "o1"
        b2_artifacts = tmp_path / "a2"
        b2_output = tmp_path / "o2"
        for d in [b1_artifacts, b1_output, b2_artifacts, b2_output]:
            d.mkdir()

        b1 = DashboardBuilder(artifacts_dir=b1_artifacts, output_dir=b1_output)
        b2 = DashboardBuilder(artifacts_dir=b2_artifacts, output_dir=b2_output)

        # Seed b1 only
        b1.conn.execute(
            "INSERT INTO test_runs (timestamp, suite, total, passed, failed, duration) VALUES (?, ?, ?, ?, ?, ?)",
            (datetime.now().isoformat(), "alpha", 10, 10, 0, 1.0),
        )
        b1.conn.commit()

        assert not b1.aggregate().empty
        assert b2.aggregate().empty

    def test_close_connection(self, builder: DashboardBuilder):
        """`close()` should terminate the SQLite connection."""
        builder.close()
        with pytest.raises(sqlite3.ProgrammingError):
            builder.conn.execute("SELECT 1")


