class TestChaos:
    """Adversarial inputs and failure injection."""

    def test_corrupt_db_file(self, tmp_path: Path):
        """A corrupt DB file should raise a clear error, not hang."""
        artifacts = tmp_path / "artifacts"
        output = tmp_path / "output"
        artifacts.mkdir()
