class TestPropertyBased:
    """Invariant testing with Hypothesis."""

    def test_aggregate_invariants(self, builder: DashboardBuilder):
        """For any valid dataset, passed + failed == total per suite."""
        from hypothesis import given, strategies as st, settings

        @given(
            st.lists(
                st.tuples(
                    st.datetimes(),
                    st.text(min_size=1, max_size=20),
                    st.integers(min_value=0, max_value=1000),
                    st.integers(min_value=0, max_value=1000),
                    st.floats(min_value=0, max_value=100),
                ),
                min_size=1,
                max_size=50,
            )
        )
        @settings(max_examples=50)
        def _check(data):
            conn = builder.conn
            for ts, suite, total, passed, duration in data:
                failed = total - passed
                if failed < 0:
                    continue  # skip invalid combos
                conn.execute(
                    "INSERT INTO test_runs (timestamp, suite, total, passed, failed, duration) VALUES (?, ?, ?, ?, ?, ?)",
                    (ts.isoformat(), suite, total, passed, failed, duration),
                )
            conn.commit()

            df = builder.aggregate()
            for _, row in df.iterrows():
                assert row["passed"] + row["failed"] == row["total"]

        _check()


